3734	    // The "Printer added" cards the page draws in this session's thread.
3735	    std::vector<nlohmann::json> live_receipts() const
3736	    {
3737	        std::vector<nlohmann::json> receipts;
3738	        if (live_panel()->host() == nullptr)
3739	            return receipts;
3740	        for (const nlohmann::json& block : live_panel()->session_json().value("blocks", nlohmann::json::array()))
